desktops.template:
spawn-at-startup "$binary"

// 原生面板是 Overlay 浮动覆盖层，不使用普通窗口的 open-floating。
layer-rule {
    match namespace=$identity_pattern
    opacity 1.0
    shadow { off; }
    background-effect { blur false; }
}

binds {
    $binding repeat=false { spawn "$binary" "lookup"; }
}

-- 原生面板是 Overlay 浮动覆盖层，不使用普通窗口的 float/pin 规则。
hl.layer_rule({
    match = { namespace = $identity_pattern },
    no_anim = true,
    blur = false,
    blur_popups = false,
    dim_around = false,
    above_lock = 0,
})

hl.on("hyprland.start", function()
    hl.exec_cmd("$binary")
end)

hl.bind("$binding", hl.dsp.exec_cmd("$lookup"), {
    repeating = false,
    description = "$product — 明确查词",
})
